import { Logger } from '@migaia/logger'
import { batch, http, level } from '@migaia/logger/plugins'

const log = new Logger({
  execution: { mutationTimeoutMs: false, pipelineDrainTimeoutMs: 5_000 },
  plugins: [
    level({ level: 'info' }),
    batch({ maxSize: 50, maxWaitMs: 1_000 }),
    http({ url: 'https://logs.example/v1/entries' })
  ]
})

const stopFailureObservation = log.onFailure(({ source, error }) => {
  console.error(`[logger:${source}]`, error)
})

try {
  log.info('checkout completed: %s', 'order-42')
  await log.flush()
} finally {
  stopFailureObservation()
  await log.shutdown('manual')
}

const audit = new Logger({
  execution: { mutationTimeoutMs: false, pipelineDrainTimeoutMs: false },
  topic: 'audit'
})
audit.useSink((entry) => sendToAuditSystem(entry))

const api = new Logger({
  execution: { mutationTimeoutMs: false, pipelineDrainTimeoutMs: false },
  topic: 'api'
})
api.extends(audit)

api.log('info', 'user created') // 同时经过 api 自己的 pipeline/sink，也完整转发给 audit

import { getLoggerRuntimeManager, setLoggerRuntimeManager } from '@migaia/logger'

const previous = getLoggerRuntimeManager()
const restore = setLoggerRuntimeManager({
  randomUUID: () => crypto.randomUUID(),
  defer: (task) => queueMicrotask(task),
  write: (text) => console.log(text),
  fetch: (url, init) => fetch(url, init)
})

try {
  // 在这段作用域内创建和使用的 Logger 都会用上面这份能力
} finally {
  restore() // 恢复到替换之前的 runtime manager
}

